  "replacement_segments": [
    {
      "id": "s2",
      "text": "Lina looked at the old fox, sensing that he was hiding a great deal of sadness behind his gruff warnings. She knew she could not simply walk away from the mystery of the humming, so she held her ground, waiting to see what the fox would do next."
    },
    {
      "id": "s3",
      "text": "Mosk pointed sternly at the door, but Lina reached into her pocket and pulled out the last apple of the season. She set it on the step between them and whispered that it was for the trouble of her visit. Mosk stared at the apple for a long time, his eyes softening. Without a word, he stood up, straightened his green vest, and stepped onto the first stair to lead her down."
    }
  ],
  "active_scene_id": "s2"
